import{_ as l,I as t,o as n,c as d,b6 as e,j as o,J as i,w as h}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"신선식품 전자상거래 마이크로서비스 시스템 개발 실전","description":"","frontmatter":{},"headers":[],"relativePath":"ko-kr/stage-2/assignments/simple-grocery-microservices/index.md","filePath":"ko-kr/stage-2/assignments/simple-grocery-microservices/index.md"}'),c={name:"ko-kr/stage-2/assignments/simple-grocery-microservices/index.md"},p={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const r=t("StepBar"),s=t("ClientOnly");return n(),d("div",null,[a[0]||(a[0]=e('<h1 id="신선식품-전자상거래-마이크로서비스-시스템-개발-실전" tabindex="-1">신선식품 전자상거래 마이크로서비스 시스템 개발 실전 <a class="header-anchor" href="#신선식품-전자상거래-마이크로서비스-시스템-개발-실전" aria-label="Permalink to “신선식품 전자상거래 마이크로서비스 시스템 개발 실전”">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to “개요”">​</a></h2><p>이 실전 프로젝트에서는 실제 PRD를 바탕으로 신선식품 전자상거래 마이크로서비스 시스템을 처음부터 완성하게 됩니다. 앞선 단일 서비스 프로젝트와 달리, 이 프로젝트의 백엔드는 비즈니스별로 여러 독립적인 서비스로 분할되며, API 게이트웨이를 통해 통일된 외부 인터페이스를 제공합니다. 서비스 경계를 설계하는 방법과, 서비스 간 데이터 일관성 문제를 처리하는 방법을 배우게 됩니다.</p><p>이 프로젝트는 Stage 2의 종합 실전环节입니다. 마이크로서비스 아키텍처는 실제 업무에서 매우 흔하게 사용됩니다. 서비스 분할과 게이트웨이 라우팅의 기본 사고방식을 익히면, 더 복잡한 백엔드 시스템 설계에 대응할 수 있게 됩니다.</p><h2 id="사전-지식" tabindex="-1">사전 지식 <a class="header-anchor" href="#사전-지식" aria-label="Permalink to “사전 지식”">​</a></h2><p>이 프로젝트를 시작하기 전에 다음 내용을 이미 숙지하고 있어야 합니다:</p><ul><li>프론트엔드 페이지 디자인 및 컴포넌트 라이브러리 사용 (<a href="./../../frontend/ui-design/">UI 디자인</a>, <a href="./../../frontend/modern-component-library/">모던 컴포넌트 라이브러리</a>)</li><li>백엔드 API 설계 및 개발 (<a href="./../../backend/ai-interface-code/">API 코드 작성</a>)</li><li>데이터베이스 기초와 Supabase (<a href="./../../backend/database-supabase/">데이터베이스부터 Supabase까지</a>)</li><li>Git 워크플로우 및 배포 (<a href="./../../backend/git-workflow/">Git과 GitHub</a>, <a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포</a>)</li></ul><h2 id="학습-목표" tabindex="-1">학습 목표 <a class="header-anchor" href="#학습-목표" aria-label="Permalink to “학습 목표”">​</a></h2><p>이 실전을 완료하면 다음을 할 수 있게 됩니다:</p><ol><li>PRD를 읽고 마이크로서비스 시스템의 개발 작업 목록을 추출하기</li><li>비즈니스 도메인별로 서비스 경계를 분할하기 (인증, 상품, 재고, 주문)</li><li>API 게이트웨이 라우팅을 설계하고 구현하기</li><li>재고 차감과 주문 일관성 등 서비스 간 문제를 처리하기</li><li>엔드투엔드 연동 테스트를 완료하고 데모 가능한 마이크로서비스 프로토타입을 전달하기</li></ol><h2 id="프로젝트-소개" tabindex="-1">프로젝트 소개 <a class="header-anchor" href="#프로젝트-소개" aria-label="Permalink to “프로젝트 소개”">​</a></h2><p>구축할 제품은 신선식품 전자상거래 마이크로서비스 시스템입니다:</p><table tabindex="0"><thead><tr><th>하위 시스템</th><th>역할</th></tr></thead><tbody><tr><td><strong>사용자 측</strong></td><td>상품 탐색, 주문, 주문 확인</td></tr><tr><td><strong>관리 측</strong></td><td>상품 관리, 재고 관리, 주문 관리</td></tr></tbody></table><p>백엔드는 비즈니스별로 다음과 같이 분할됩니다:</p><table tabindex="0"><thead><tr><th>서비스</th><th>역할</th></tr></thead><tbody><tr><td><strong>API Gateway</strong></td><td>통일된 진입점, 라우팅 전달, 인증 검증</td></tr><tr><td><strong>Auth Service</strong></td><td>사용자 회원가입, 로그인, JWT 발급</td></tr><tr><td><strong>Catalog Service</strong></td><td>상품 정보 관리</td></tr><tr><td><strong>Inventory Service</strong></td><td>재고 수량 관리</td></tr><tr><td><strong>Order Service</strong></td><td>주문 생성, 상태 관리</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 입구</p><p>이 프로젝트의 요구사항 문서는 GitHub에 있습니다: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/ko-kr/stage-2/assignments/simple-grocery-microservices/PRD.md" target="_blank" rel="noreferrer">PRD 보기</a></p></div>',16)),o("div",p,[i(s,null,{default:h(()=>[i(r,{active:0,items:[{title:"요구사항 분석",description:"PRD를 읽고 서비스 분할, 페이지, 거래 파이프라인을 명확히 합니다"},{title:"골격 구축",description:"프론트엔드, 게이트웨이, 각 서비스 골격을 생성합니다"},{title:"반복 개발",description:"모듈별로 API를 추가하고, 재고와 주문의 일관성을 수정합니다"},{title:"연동 및 배포",description:"엔드투엔드로 실행하고, 배포하여 데모를 준비합니다"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="제1부-요구사항-분석" tabindex="-1">제1부: 요구사항 분석 <a class="header-anchor" href="#제1부-요구사항-분석" aria-label="Permalink to “제1부: 요구사항 분석”">​</a></h2><h3 id="_1-1-prd-읽기" tabindex="-1">1.1 PRD 읽기 <a class="header-anchor" href="#_1-1-prd-읽기" aria-label="Permalink to “1.1 PRD 읽기”">​</a></h3><p>PRD 문서를 열고 다음 질문에 중점적으로 답해보세요:</p><ul><li>서비스를 어떻게 분할하는가? 각 서비스의 책임 경계는 무엇인가?</li><li>사용자 측과 관리 측에 각각 어떤 페이지가 있는가?</li><li>주문 후 재고 차감 전략은 무엇인가? 성공 / 실패 / 시간 초과 시 각각 어떻게 처리하는가?</li><li>첫 번째 버전에서 어떤 복잡한 역량(예: 분산 트랜잭션, 메시지 큐)을 일단 제외하는가?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>위 질문들에 명확한 답이 없다면, 코드 작성을 시작하지 마세요. 요구사항 이해가 불충분한 것은 재작업의 가장 흔한 원인입니다.</p></div><h3 id="_1-2-시스템-아키텍처-확인" tabindex="-1">1.2 시스템 아키텍처 확인 <a class="header-anchor" href="#_1-2-시스템-아키텍처-확인" aria-label="Permalink to “1.2 시스템 아키텍처 확인”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; fe[&quot;프론트엔드 페이지&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fe --&gt; gw[&quot;API Gateway&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; auth[&quot;Auth Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; catalog[&quot;Catalog Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; inventory[&quot;Inventory Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; order[&quot;Order Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order --&gt; inventory</span></span></code></pre></div><h2 id="제2부-프로젝트-골격-구축" tabindex="-1">제2부: 프로젝트 골격 구축 <a class="header-anchor" href="#제2부-프로젝트-골격-구축" aria-label="Permalink to “제2부: 프로젝트 골격 구축”">​</a></h2><h3 id="_2-1-프로젝트-구조-생성" tabindex="-1">2.1 프로젝트 구조 생성 <a class="header-anchor" href="#_2-1-프로젝트-구조-생성" aria-label="Permalink to “2.1 프로젝트 구조 생성”">​</a></h3><p>프롬프트 참고:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>현재 PRD를 바탕으로 신선식품 전자상거래 마이크로서비스 시스템의 프로젝트 골격을 생성해 주세요.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>요구사항:</span></span>
<span class="line"><span>1. 프론트엔드 사용자 측과 관리 측 골격을 생성합니다</span></span>
<span class="line"><span>2. api-gateway, auth-service, catalog-service, inventory-service, order-service 다섯 개의 디렉토리를 생성합니다</span></span>
<span class="line"><span>3. 각 서비스는 먼저 최소 실행 가능 진입점만 만듭니다</span></span>
<span class="line"><span>4. 실제 데이터베이스와 결제는 아직 연결하지 않습니다</span></span></code></pre></div><h3 id="_2-2-프로젝트-구조-확인" tabindex="-1">2.2 프로젝트 구조 확인 <a class="header-anchor" href="#_2-2-프로젝트-구조-확인" aria-label="Permalink to “2.2 프로젝트 구조 확인”">​</a></h3><p>항목별 확인:</p><ul><li>[ ] 다섯 개의 서비스 디렉토리 구조가 명확한가</li><li>[ ] API Gateway가 시작되고 요청을 전달할 수 있는가</li><li>[ ] 각 서비스의 헬스 체크 API가 사용 가능한가</li><li>[ ] 프론트엔드 사용자 측과 관리 측 페이지에 접근 가능한가</li></ul><h2 id="제3부-반복-개발" tabindex="-1">제3부: 반복 개발 <a class="header-anchor" href="#제3부-반복-개발" aria-label="Permalink to “제3부: 반복 개발”">​</a></h2><h3 id="_3-1-모듈별-진행" tabindex="-1">3.1 모듈별 진행 <a class="header-anchor" href="#_3-1-모듈별-진행" aria-label="Permalink to “3.1 모듈별 진행”">​</a></h3><ol><li><strong>API Gateway</strong>: 라우팅 설정, JWT 검증 미들웨어</li><li><strong>Auth Service</strong>: 회원가입, 로그인, JWT 발급</li><li><strong>Catalog Service</strong>: 상품 CRUD, 목록 조회</li><li><strong>Inventory Service</strong>: 재고 조회, 재고 차감</li><li><strong>Order Service</strong>: 주문 생성, 상태 전환, 재고 연동</li><li><strong>관리 측</strong>: 상품 관리, 재고 관리, 주문 관리</li></ol><h3 id="_3-2-모듈-자체-점검" tabindex="-1">3.2 모듈 자체 점검 <a class="header-anchor" href="#_3-2-모듈-자체-점검" aria-label="Permalink to “3.2 모듈 자체 점검”">​</a></h3><table tabindex="0"><thead><tr><th>점검 항목</th><th>검증 방법</th></tr></thead><tbody><tr><td>게이트웨이 라우팅</td><td>각 서비스 API가 게이트웨이를 통해 올바르게 전달되는가</td></tr><tr><td>권한 격리</td><td>사용자 측과 관리 측 API가 격리되어 있는가</td></tr><tr><td>데이터 일관성</td><td>상품과 재고 데이터가 동기화되어 있는가</td></tr><tr><td>거래 루프</td><td>주문 후 재고 차감, 주문 상태가 일치하는가</td></tr><tr><td>실패 처리</td><td>재고 부족이나 시간 초과 시 보상 메커니즘이 있는가</td></tr></tbody></table><h2 id="제4부-연동-및-배포" tabindex="-1">제4부: 연동 및 배포 <a class="header-anchor" href="#제4부-연동-및-배포" aria-label="Permalink to “제4부: 연동 및 배포”">​</a></h2><h3 id="_4-1-엔드투엔드-테스트" tabindex="-1">4.1 엔드투엔드 테스트 <a class="header-anchor" href="#_4-1-엔드투엔드-테스트" aria-label="Permalink to “4.1 엔드투엔드 테스트”">​</a></h3><p>최소한 다음 시나리오를 검증하세요:</p><ul><li>상품 탐색 → 장바구니에 추가 → 주문 → 주문 확인</li><li>관리자 → 상품 추가 → 재고 업데이트 → 주문 확인</li></ul><h2 id="산출물" tabindex="-1">산출물 <a class="header-anchor" href="#산출물" aria-label="Permalink to “산출물”">​</a></h2><p>이 프로젝트를 완료한 후 다음을 제출해야 합니다:</p><ul><li>[ ] 접근 가능한 온라인 데모 링크</li><li>[ ] 소스 코드 저장소 링크 (README 포함)</li><li>[ ] PRD 문서</li><li>[ ] 핵심 페이지 스크린샷 (상품 목록, 주문 페이지, 주문 내역, 관리 대시보드)</li><li>[ ] 60초 데모 영상</li></ul><h2 id="평가-기준" tabindex="-1">평가 기준 <a class="header-anchor" href="#평가-기준" aria-label="Permalink to “평가 기준”">​</a></h2><table tabindex="0"><thead><tr><th>영역</th><th>기본 요구사항</th><th>심화 요구사항</th></tr></thead><tbody><tr><td>PRD 정합성</td><td>페이지, 기능, 서비스 분할이 기본적으로 PRD에 부합</td><td>서비스 분할 이유를 명확히 설명할 수 있음</td></tr><tr><td>제품 루프</td><td>탐색 → 주문 → 재고 차감 → 주문 확인이 실행 가능</td><td>주문 시간 초과나 재고 부족 시 보상 메커니즘이 있음</td></tr><tr><td>서비스 아키텍처</td><td>각 서비스가 독립적으로 시작 가능하고 게이트웨이를 통해 통일 접근</td><td>서비스 간 통신에 오류 처리와 재시도가 있음</td></tr><tr><td>관리 기능</td><td>상품, 재고, 주문 관리가 조작 가능</td><td>관리 측에 데이터 통계가 있음</td></tr><tr><td>엔지니어링 완성도</td><td>프론트엔드, 게이트웨이, 서비스, 데이터베이스 체인이 연결됨</td><td>Docker Compose 등의 오케스트레이션이 있음</td></tr></tbody></table><h2 id="참고-자료" tabindex="-1">참고 자료 <a class="header-anchor" href="#참고-자료" aria-label="Permalink to “참고 자료”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 디자인</a></li><li><a href="./../../frontend/modern-component-library/">모던 컴포넌트 라이브러리로 인터페이스 업데이트하기</a></li><li><a href="./../../backend/database-supabase/">데이터베이스부터 Supabase까지</a></li><li><a href="./../../backend/ai-interface-code/">대형 언어 모델로 API 코드 및 문서 작성하기</a></li><li><a href="./../../backend/git-workflow/">Git 및 GitHub 워크플로우</a></li><li><a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포 방법</a></li></ul>`,30))])}const y=l(c,[["render",b]]);export{P as __pageData,y as default};
